h/tlph/karltzy.webp", "s": "https://liquipedia.net/mobilelegends/KarlTzy"}, {"r": "PH", "t": "TLPH", "h": "Sanji", "l": "MID", "p": "/players/ph/tlph/sanji.webp", "s": "https://liquipedia.net/mobilelegends/Sanji"}, {"r": "PH", "t": "TLPH", "h": "Teddy", "l": "GOLD", "p": "/players/ph/tlph/teddy.webp", "s": "https://liquipedia.net/mobilelegends/Teddyqt"}, {"r": "PH", "t": "TLPH", "h": "Jaypee", "l": "ROAM", "p": "/players/ph/tlph/jaypee.webp", "s": "https://liquipedia.net/mobilelegends/Jaypee"}, {"r": "PH", "t": "TLPH", "h": "Daiki", "l": "GOLD", "p": "", "s": "https://liquipedia.net/mobilelegends/Dai Ki"}, {"r": "PH", "t": "TNC", "h": "Ryota", "l": "EXP", "p": "/players/ph/tnc/ryota.webp", "s": "https://liquipedia.net/mobilelegends/Ryota"}, {"r": "PH", "t": "TNC", "h": "Zaida", "l": "JUNGLE", "p": "/players/ph/tnc/zaida.webp", "s": "https://liquipedia.net/mobilelegends/Zaida"}, {"r": "PH", "t": "TNC", "h": "Vin", "l": "MID", "p": "/players/ph/tnc/vin.webp", "s": "https://liquipedia.net/mobilelegends/Vinnn"}, {"r": "PH", "t": "TNC", "h": "Jowm", "l": "GOLD", "p": "/players/ph/tnc/jowm.webp", "s": "https://liquipedia.net/mobilelegends/Jowm"}, {"r": "PH", "t": "TNC", "h": "Zehn", "l": "ROAM", "p": "", "s": "https://liquipedia.net/mobilelegends/Zehn"}, {"r": "PH", "t": "TNC", "h": "Yeyeniya", "l": "EXP", "p": "", "s": "https://liquipedia.net/mobilelegends/Lift"}, {"r": "PH", "t": "TWIS", "h": "Lansu", "l": "EXP", "p": "/players/ph/twis/lansu.webp", "s": "https://liquipedia.net/mobilelegends/Lansu"}, {"r": "PH", "t": "TWIS", "h": "Sensu1", "l": "JUNGLE", "p": "/players/ph/twis/sensu1.webp", "s": "https://liquipedia.net/mobilelegends/Sensui"}, {"r": "PH", "t": "TWIS", "h": "Sionnn", "l": "MID", "p": "/players/ph/twis/sionnn.webp", "s": "https://liquipedia.net/mobilelegends/Sionnn"}, {"r": "PH", "t": "TWIS", "h": "Bennyqt", "l": "GOLD", "p": "/players/ph/twis/bennyqt.webp", "s": "https://liquipedia.net/mobilelegends/Bennyqt"}, {"r": "PH", "t": "TWIS", "h": "Tracy", "l": "ROAM", "p": "/players/ph/twis/tracy.webp", "s": "https://liquipedia.net/mobilelegends/Tracy"}, {"r": "PH", "t": "TWIS", "h": "Kurtt", "l": "MID", "p": "", "s": "https://liquipedia.net/mobilelegends/Super Kurt"}]'::jsonb;
begin
  -- 1. Handle Canonical Merges & Deduplication (Merge 'Chibi' -> 'Chibii')
  select id into v_chibi_id from public.players where handle = 'Chibi';
  select id into v_chibii_id from public.players where handle = 'Chibii';
  
  if v_chibi_id is not null and v_chibii_id is not null and v_chibi_id <> v_chibii_id then
    if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'player_match_stats') then
      execute 'update public.player_match_stats set player_id = $1 where player_id = $2' using v_chibii_id, v_chibi_id;
    end if;
    if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'lineup_players') then
      execute 'update public.lineup_players set player_id = $1 where player_id = $2' using v_chibii_id, v_chibi_id;
    end if;
    if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'draft_picks') then
      execute 'update public.draft_picks set player_id = $1 where player_id = $2' using v_chibii_id, v_chibi_id;
    end if;
    if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'weekly_mvp_predictions') then
      execute 'update public.weekly_mvp_predictions set player_id = $1 where player_id = $2' using v_chibii_id, v_chibi_id;
    end if;
    if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'season_rosters') then
      execute 'delete from public.season_rosters where player_id = $1' using v_chibi_id;
    end if;
    delete from public.players where id = v_chibi_id;
  elsif v_chibi_id is not null and v_chibii_id is null then
    update public.players set handle = 'Chibii' where id = v_chibi_id;
  end if;

  -- 2. Deactivate obsolete uppercase and departed seed players
  update public.season_rosters
  set active = false
  where season_id in (select id from public.seasons where season_number = 18)
    and player_id in (
      select id from public.players
      where handle in (
        'SEPAT', 'CHIBI', 'CHIBII', 'CIKUGAIS', 'ADDBOYY', 'CLAWKUN', 'SUPERKENN',
        'ABOYY', 'APRHO', 'MARTZYY', 'RENDYYY', 'KRAMM', 'YUMS', 'BRAVO',
        'FACEHUGGER', 'HAN', 'LAUFEYSON', 'SMOOTH'
      )
    );

  -- 3. Upsert All 160 Official Season 18 Players & Rosters
  for item in select * from jsonb_array_elements(roster_data) loop
    select id into v_season_id 
    from public.seasons 
    where region_code = item->>'r' and season_number = 18;
    
    if v_season_id is null then continue; end if;

    select id into v_team_id 
    from public.teams 
    where code = item->>'t' and region_code = item->>'r';
    
    if v_team_id is null then continue; end if;

    insert into public.players (handle, country_code, photo_url, source_url, verified_at)
    values (
      item->>'h', 
      item->>'r', 
      nullif(item->>'p', ''), 
      nullif(item->>'s', ''), 
      now()
    )
    on conflict (handle) do update set
      photo_url = coalesce(nullif(excluded.photo_url, ''), public.players.photo_url),
      source_url = coalesce(nullif(excluded.source_url, ''), public.players.source_url),
      verified_at = now()
    returning id into v_player_id;

    if v_player_id is null then
      select id into v_player_id from public.players where handle = item->>'h';
    end if;

    insert into public.season_rosters (season_id, player_id, team_id, role, starts_at, active, source_url, verified_at)
    values (
      v_season_id, 
      v_player_id, 
      v_team_id, 
      item->>'l', 
      '2026-08-14T00:00:00Z'::timestamptz, 
      true, 
      nullif(item->>'s', ''), 
      now()
    )
    on conflict (season_id, player_id, starts_at) do update set
      team_id = excluded.team_id,
      role = excluded.role,
      active = true,
      source_url = coalesce(excluded.source_url, public.season_rosters.source_url),
      verified_at = now();

    update public.season_rosters 
    set active = false 
    where season_id = v_season_id and player_id = v_player_id and team_id <> v_team_id;

  end loop;

  -- Specifically ensure Sepat is active on Team Rey (TR) only, not Vamos (VMS)
  select id into v_player_id from public.players where handle = 'Sepat';
  if v_player_id is not null then
    update public.season_rosters
    set active = false
    where player_id = v_player_id
      and team_id in (select id from public.teams where code = 'VMS');
  end if;

end $$;

-- Verification summary
select
  s.region_code as region,
  count(distinct sr.player_id) as active_players,
  count(distinct sr.team_id) as active_teams
from public.season_rosters sr
join public.seasons s on s.id = sr.season_id
where sr.active = true and s.season_number = 18
group by s.region_code
order by s.region_code;
